"use strict";

/**
 * The gallery is DATA-DRIVEN. Project entries come from ./catalog.json,
 * generated by scripts/build-catalog.mjs during GitHub Actions deployment.
 * Do not hand-edit a project array here when publishing a new extension.
 */
const BASE = "https://github.com/RuslanSharifov/chrome-ui-gallery/";
const RAW = "https://raw.githubusercontent.com/RuslanSharifov/chrome-ui-gallery/main/";
const grid = document.getElementById("project-grid");
const count = document.getElementById("results-count");
const empty = document.getElementById("empty-state");
const search = document.getElementById("search");
const categoryButtons = Array.from(document.querySelectorAll("[data-category]"));
const platformOptions = document.querySelector(".platform-options");
const state = {category:"all",platform:"all",style:"all",sort:"name",query:""};
const page = document.body.dataset.page || "gallery";
const LIMIT = Number(grid && grid.dataset.limit) || 6;
const allLink = document.getElementById("view-all");
const styleFilter=document.getElementById("style-filter");
const sortFilter=document.getElementById("sort-filter");
let projects = [];
let platformButtons = [];

function node(tag,className,text) {
  const el=document.createElement(tag);
  if(className)el.className=className;
  if(text!==undefined)el.textContent=text;
  return el;
}
function githubPath(path) {
  return path.split("/").map(part=>encodeURIComponent(part)).join("/");
}
function sourceLink(path,isFolder) {
  return BASE + (isFolder ? "tree/main/" : "blob/main/") + githubPath(path);
}
function buildCard(project) {
  const card=node("article","project-card");
  const visual=node("div","project-visual"+(project.category==="tool"?" tool-visual":""));
  const palette=project.palette;
  visual.style.setProperty("--v1",palette[0]);
  visual.style.setProperty("--v2",palette[1]);
  visual.style.setProperty("--glow",palette[2]);
  visual.append(node("span","visual-top-label",project.category==="ui"?"VISUAL EXPERIMENT":"BROWSER TOOL"));
  const windowEl=node("div","visual-window");
  const dots=node("div","visual-window-head");
  for(let i=0;i<3;i++)dots.append(node("i"));
  windowEl.append(dots);
  const lines=node("div","visual-window-lines");
  for(let i=0;i<3;i++)lines.append(node("i"));
  windowEl.append(lines);
  visual.append(windowEl,node("span","visual-monogram",project.icon));
  if(project.preview) {
    const image=node("img","project-preview-image");
    image.src=RAW+githubPath(project.preview);
    image.alt="";
    image.loading="lazy";
    image.decoding="async";
    image.addEventListener("error",()=>image.remove(),{once:true});
    visual.append(image);
  }

  const info=node("div","project-info");
  const kicker=node("div","project-kicker");
  kicker.append(node("span","",project.platform.toUpperCase()),node("span","",project.style));
  info.append(kicker,node("h3","",project.name),node("p","",project.description));
  if(project.author) {
    const byline=node("div","author-byline");
    byline.append(node("span","","By "));
    if(project.author.url){
      const author=node("a","",project.author.name);
      author.href=project.author.url;
      author.rel="noopener noreferrer";
      author.target="_blank";
      byline.append(author);
    } else {
      byline.append(node("span","",project.author.name));
    }
    info.append(byline);
  }
  const tags=node("div","tags");
  for(const tag of project.tags)tags.append(node("span","",tag));
  info.append(tags);
  const actions=node("div","project-actions");
  const primary=node("a","",project.category==="tool"?"View tool →":"Explore design →");
  primary.href=sourceLink(project.doc,false);
  primary.target="_blank";primary.rel="noopener noreferrer";
  primary.setAttribute("aria-label","Read documentation for "+project.name+" on GitHub");
  const source=node("a","","Source ↗");
  source.href=sourceLink(project.folder,true);
  source.target="_blank";source.rel="noopener noreferrer";
  source.setAttribute("aria-label","View source files for "+project.name+" on GitHub");
  actions.append(primary,source);
  const download=node("a","download-action","↓ Download ZIP");
  download.href="./downloads/"+encodeURIComponent(project.id)+".zip";
  download.download=project.id+".zip";
  download.setAttribute("aria-label","Download "+project.name+" extension ZIP");
  actions.append(download);
  info.append(actions);
  card.append(visual,info);
  card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Open '+project.name);
  card.addEventListener('click',e=>{if(!e.target.closest('a,button'))openDetail(project)});
  card.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&!e.target.closest('a,button')){e.preventDefault();openDetail(project)}});
  return card;
}

function openDetail(p){
 const focused=document.activeElement,photos=[...new Set([...(p.previews||[]),p.preview].filter(Boolean))];let current=0;
 const overlay=node('div','gallery-overlay'),modal=node('section','gallery-modal');
 modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label',p.name);
 const header=node('div','gallery-modal-head'),close=node('button','','×');
 close.setAttribute('aria-label','Close');header.append(node('h2','',p.name),close);
 const viewer=node('div','gallery-viewer'),img=node('img',''),count=node('span','gallery-counter');
 const prev=node('button','gallery-prev','‹'),next=node('button','gallery-next','›');
 prev.setAttribute('aria-label','Previous screenshot');next.setAttribute('aria-label','Next screenshot');
 function change(n){if(!photos.length)return;current=(current+n+photos.length)%photos.length;img.src=RAW+githubPath(photos[current]);img.alt=p.name+' screenshot '+(current+1);count.textContent=(current+1)+' / '+photos.length}
 if(photos.length){viewer.append(img);if(photos.length>1){viewer.append(prev,next,count);prev.onclick=()=>change(-1);next.onclick=()=>change(1)}change(0)}
 else viewer.append(node('p','','No screenshots available'));
 let touch=0;viewer.addEventListener('touchstart',e=>touch=e.changedTouches[0].clientX,{passive:true});
 viewer.addEventListener('touchend',e=>{let d=e.changedTouches[0].clientX-touch;if(Math.abs(d)>45)change(d<0?1:-1)},{passive:true});
 const details=node('div','gallery-details');
 details.append(node('p','gallery-meta',p.platform+' · '+p.style),node('p','',p.description));
 if(p.version)details.append(node('p','gallery-meta','Version '+p.version));
 if(p.author?.name)details.append(node('p','gallery-meta','By '+p.author.name));
 const tags=node('div','tags');p.tags.forEach(t=>tags.append(node('span','',t)));details.append(tags);
 const links=node('div','gallery-detail-links');
 for(const [label,url] of [['Documentation',sourceLink(p.doc,false)],['Source',sourceLink(p.folder,true)],['Download ZIP','./downloads/'+encodeURIComponent(p.id)+'.zip']]){
 const a=node('a','button button-secondary',label);a.href=url;if(label==='Download ZIP')a.download=p.id+'.zip';else{a.target='_blank';a.rel='noopener noreferrer'}links.append(a)}
 details.append(links);modal.append(header,viewer,details);overlay.append(modal);document.body.append(overlay);
 document.body.style.overflow='hidden';
 function dismiss(){overlay.remove();document.body.style.overflow='';document.removeEventListener('keydown',keys);focused?.focus?.()}
 function keys(e){if(e.key==='Escape')dismiss();if(e.key==='ArrowRight')change(1);if(e.key==='ArrowLeft')change(-1);
 if(e.key==='Tab'){const a=[...modal.querySelectorAll('button,a[href]')];if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}}
 close.onclick=dismiss;overlay.onclick=e=>{if(e.target===overlay)dismiss()};document.addEventListener('keydown',keys);close.focus();
}
const galleryStyles=document.createElement('style');
galleryStyles.textContent=String.raw`
.project-card{cursor:pointer}.project-card:focus-visible{outline:2px solid var(--lav)}
.gallery-overlay{position:fixed;inset:0;z-index:150;background:#03050de0;backdrop-filter:blur(14px);display:flex;align-items:center;justify-content:center;padding:20px}
.gallery-modal{width:min(850px,100%);max-height:92dvh;overflow:auto;overscroll-behavior:contain;background:#121522;border:1px solid #ffffff30;border-radius:24px}
.gallery-modal-head{position:sticky;top:0;z-index:3;background:#121522;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 20px;border-bottom:1px solid #ffffff22}
.gallery-modal-head h2{font-size:clamp(1.1rem,3vw,1.6rem)}.gallery-modal-head button{background:#ffffff18;border:1px solid #ffffff30;border-radius:50%;width:38px;height:38px;font-size:26px;cursor:pointer;flex:none}
.gallery-viewer{position:relative;aspect-ratio:16/9;background:#080a12;display:grid;place-items:center;overflow:hidden;touch-action:pan-y}
.gallery-viewer img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}
.gallery-prev,.gallery-next{position:absolute;top:50%;transform:translateY(-50%);border-radius:50%;border:1px solid #ffffff40;background:#080a12cc;width:42px;height:42px;font-size:28px;cursor:pointer}
.gallery-prev{left:12px}.gallery-next{right:12px}.gallery-counter{position:absolute;bottom:12px;background:#080a12dd;border-radius:30px;padding:3px 12px}
.gallery-details{padding:22px;display:grid;gap:14px;overflow-wrap:anywhere}.gallery-meta{color:var(--lav);font-size:.85rem}.gallery-detail-links{display:flex;flex-wrap:wrap;gap:10px}.gallery-detail-links .button{padding:10px 15px;font-size:.85rem}
@media(max-width:600px){.gallery-overlay{padding:0;align-items:flex-end}.gallery-modal{width:100%;max-height:94dvh;border-radius:24px 24px 0 0;padding-bottom:env(safe-area-inset-bottom);animation:galleryRise .25s ease-out}.gallery-viewer{aspect-ratio:4/3;min-height:180px}.gallery-details{padding:18px}.gallery-detail-links .button{flex:1 1 auto}}
@keyframes galleryRise{from{transform:translateY(100%)}to{transform:translateY(0)}}@media(prefers-reduced-motion:reduce){.gallery-modal{animation:none}}
`;
document.head.append(galleryStyles);

function setActive(buttons,key,value) {
  for(const button of buttons) {
    const selected=button.dataset[key]===value;
    button.classList.toggle("active",selected);
    button.setAttribute("aria-pressed",String(selected));
  }
}
function makePlatformButtons() {
  if(!platformOptions)return;
  const preferred=["chatgpt","gemini","github","lovable","browser"];
  const present=[...new Set(projects.map(p=>p.platform))];
  present.sort((a,b)=>{
    const aa=preferred.indexOf(a),bb=preferred.indexOf(b);
    return (aa===-1?preferred.length:aa)-(bb===-1?preferred.length:bb)||a.localeCompare(b);
  });
  platformButtons=[];
  for(const platform of ["all",...present]){
    const label=platform==="all"?"All":platform==="browser"?"Browser":platform.charAt(0).toUpperCase()+platform.slice(1);
    const button=node("button","platform-button",label);
    button.type="button";
    button.dataset.platform=platform;
    button.setAttribute("aria-pressed",String(platform==="all"));
    if(platform==="all")button.classList.add("active");
    button.addEventListener("click",()=>{
      state.platform=platform;
      setActive(platformButtons,"platform",state.platform);
      render();
    });
    platformButtons.push(button);
  }
  platformOptions.replaceChildren(...platformButtons);
}
function makeStyleOptions(){
  if(!styleFilter)return;
  const styles=[...new Set(projects.map(p=>p.style))].sort((a,b)=>a.localeCompare(b));
  styleFilter.replaceChildren(new Option("All styles","all"),...styles.map(s=>new Option(s,s)));
}
function sortProjects(items){
  const sorted=[...items];
  const compare=(a,b)=>a.localeCompare(b,undefined,{sensitivity:"base"});
  sorted.sort((a,b)=>state.sort==="name-desc"?compare(b.name,a.name):
    state.sort==="platform"?compare(a.platform,b.platform)||compare(a.name,b.name):
    state.sort==="category"?compare(a.category,b.category)||compare(a.name,b.name):
    compare(a.name,b.name));
  return sorted;
}
function updateTotals() {
  const ui=projects.filter(p=>p.category==="ui").length;
  const tools=projects.length-ui;
  const platforms=new Set(projects.filter(p=>p.category==="ui").map(p=>p.platform)).size;
  const values={all:projects.length,ui,tool:tools,platforms};
  for(const element of document.querySelectorAll("[data-stat]")){
    const value=values[element.dataset.stat];
    if(value!==undefined)element.textContent=String(value).padStart(2,"0");
  }
  for(const button of categoryButtons) {
    const span=button.querySelector("span");
    if(span)span.textContent=String(values[button.dataset.category]).padStart(2,"0");
  }
}
function latestProjects() {
  /* Optional "added" (ISO date) in catalog entries; otherwise the newest entries are the last ones in catalog order. */
  const indexed=projects.map((p,i)=>({p,i}));
  const hasDates=projects.some(p=>typeof p.added==="string");
  indexed.sort((a,b)=>hasDates?String(b.p.added||"").localeCompare(String(a.p.added||""))||b.i-a.i:b.i-a.i);
  return indexed.slice(0,LIMIT).map(x=>x.p);
}
function render() {
  if(page==="home"){
    const latest=latestProjects();
    grid.replaceChildren(...latest.map(buildCard));
    if(count)count.textContent="Latest "+latest.length+" of "+projects.length;
    if(allLink)allLink.firstChild.textContent="View all "+projects.length+" repositories ";
    return;
  }
  const query=state.query.trim().toLowerCase();
  const matched=projects.filter(item=>{
    if(state.category!=="all"&&item.category!==state.category)return false;
    if(state.platform!=="all"&&item.platform!==state.platform)return false;
    if(state.style!=="all"&&item.style!==state.style)return false;
    const searchable=[item.name,item.platform,item.style,item.description,item.author?.name??"",...item.tags].join(" ").toLowerCase();
    return !query||searchable.includes(query);
  });
  grid.replaceChildren(...sortProjects(matched).map(buildCard));
  count.textContent=String(matched.length)+" "+(matched.length===1?"project":"projects");
  empty.hidden=matched.length>0;
  history.replaceState(null,"",location.pathname+(state.category!=="all"?"?category="+state.category:""));
}
for(const button of categoryButtons) {
  button.addEventListener("click",()=>{
    state.category=button.dataset.category;
    setActive(categoryButtons,"category",state.category);
    render();
  });
}
search?.addEventListener("input",()=>{state.query=search.value;render()});
styleFilter?.addEventListener("change",()=>{state.style=styleFilter.value;render()});
sortFilter?.addEventListener("change",()=>{state.sort=sortFilter.value;render()});
document.getElementById("reset-advanced")?.addEventListener("click",resetFilters);
function resetFilters(){
  state.category="all";state.platform="all";state.style="all";state.sort="name";state.query="";
  search.value="";styleFilter.value="all";sortFilter.value="name";
  setActive(categoryButtons,"category","all");setActive(platformButtons,"platform","all");
  render();
}
document.getElementById("clear-filters")?.addEventListener("click",()=>{
  resetFilters();
  search?.focus();
});
document.addEventListener("keydown",event=>{
  const active=document.activeElement;
  const editing=active&&["INPUT","TEXTAREA"].includes(active.tagName);
  if(search&&event.key==="/"&&!editing&&!event.ctrlKey&&!event.metaKey&&!event.altKey){
    event.preventDefault();search.focus();
  }
  if(search&&event.key==="Escape"&&active===search)search.blur();
});
function applyUrlState(){
  const q=new URLSearchParams(location.search);
  const cat=q.get("category"),plat=q.get("platform"),text=q.get("q");
  if(["ui","tool"].includes(cat)){state.category=cat;setActive(categoryButtons,"category",cat)}
  if(plat&&projects.some(p=>p.platform===plat)){state.platform=plat;setActive(platformButtons,"platform",plat)}
  if(text&&search){state.query=text;search.value=text}
}
function validateCatalog(data) {
  if(!data||data.schemaVersion!==1||!Array.isArray(data.projects))throw new Error("Unexpected catalog format");
  const ids=new Set();
  return data.projects.map(item=>{
    if(typeof item.id!=="string"||ids.has(item.id)||
       !["ui","tool"].includes(item.category)||
       !["name","description","platform","style","doc","folder","icon"].every(k=>typeof item[k]==="string")||
       !Array.isArray(item.tags)||!item.tags.every(t=>typeof t==="string")||
       !Array.isArray(item.palette)||item.palette.length!==3||
       !item.palette.every(s=>typeof s==="string"&&/^#[0-9a-fA-F]{6}$/.test(s))||
       item.preview!==undefined&&typeof item.preview!=="string"||item.previews!==undefined&&(!Array.isArray(item.previews)||!item.previews.every(x=>typeof x==="string")))
      throw new Error("Invalid project catalog entry");
    ids.add(item.id);
    return item;
  });
}
async function loadCatalog() {
  if(count)count.textContent="Loading projects…";
  try {
    const response=await fetch("./catalog.json",{cache:"no-store"});
    if(!response.ok)throw new Error("Catalog request failed: "+response.status);
    const data=await response.json();
    projects=validateCatalog(data);
    makePlatformButtons();
    makeStyleOptions();
    updateTotals();
    if(page!=="home")applyUrlState();
    render();
  } catch(error) {
    if(count)count.textContent="Catalog unavailable";
    grid.replaceChildren();
    if(!empty)return;
    empty.hidden=false;
    empty.querySelector("h3").textContent="The gallery is temporarily unavailable.";
    empty.querySelector("p").textContent="Please refresh the page or browse the projects directly on GitHub.";
    const button=document.getElementById("clear-filters");
    button.textContent="Refresh gallery";
    button.onclick=()=>window.location.reload();
    // Accessible error, with developer details in the console.
    console.error("Chrome UI Gallery:",error);
  }
}
if(grid)loadCatalog();

/* GitHub public contributor endpoint; never fabricate identities or counts. */
async function loadContributors(){
  const container=document.getElementById("contributors-grid");
  if(!container)return;
  try{
    const response=await fetch("https://api.github.com/repos/RuslanSharifov/chrome-ui-gallery/contributors?per_page=100",{headers:{Accept:"application/vnd.github+json"}});
    if(!response.ok)throw new Error("GitHub API "+response.status);
    const people=await response.json();
    if(!Array.isArray(people))throw new Error("Invalid contributors response");
    if(!people.length){container.textContent="No contributor data available yet.";return}
    const cards=people.filter(p=>p.type==="User"&&p.login&&p.html_url).map(p=>{
      const card=node("a","contributor-card");
      card.href=p.html_url;card.target="_blank";card.rel="noopener noreferrer";
      const avatar=node("img","contributor-avatar");
      avatar.src=p.avatar_url;avatar.alt="";avatar.loading="lazy";
      const info=node("div","");
      info.append(node("strong","",p.login),node("span","",p.contributions+" "+(p.contributions===1?"contribution":"contributions")));
      card.append(avatar,info);return card;
    });
    container.replaceChildren(...cards);
  }catch(error){
    const link=node("a","text-link","View contributors on GitHub ↗");
    link.href="https://github.com/RuslanSharifov/chrome-ui-gallery/graphs/contributors";
    link.target="_blank";link.rel="noopener noreferrer";
    container.replaceChildren(node("p","","GitHub contributor data is temporarily unavailable."),link);
  }
}
loadContributors();
